/* Sample the four source pixels used by each bilinear model-input pixel.
 * The color table is generated by the same FFmpeg converter as the full image.
 * No changes to model size, frame rate, color conversion or interpolation.
 */
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <emmintrin.h>

static const uint8_t *bgr(const uint8_t *lut, const uint8_t *y,
                          const uint8_t *u, const uint8_t *v, int x) {
    size_t color = ((size_t)u[x / 2] << 16) | ((size_t)v[x / 2] << 8) | y[x];
    return lut + 3 * color;
}

static __m128i unpack(const uint8_t *color) {
    uint32_t bytes;
    memcpy(&bytes,color,4);
    return _mm_unpacklo_epi8(_mm_cvtsi32_si128((int)bytes),_mm_setzero_si128());
}

__declspec(dllexport) void sample_yuv420(
    const uint8_t *y, const uint8_t *u, const uint8_t *v,
    int sy, int su, int sv, const uint8_t *lut,
    const int32_t *xs, const int32_t *ys, const int32_t *wx, const int32_t *wy,
    int width, int height, uint8_t *output) {
    for (int row = 0; row < height; ++row) {
        const int y0 = ys[row], y1 = y0 + 1;
        const uint8_t *l0 = y + (size_t)y0 * sy, *l1 = y + (size_t)y1 * sy;
        const uint8_t *u0 = u + (size_t)(y0 / 2) * su, *u1 = u + (size_t)(y1 / 2) * su;
        const uint8_t *v0 = v + (size_t)(y0 / 2) * sv, *v1 = v + (size_t)(y1 / 2) * sv;
        /* At 1920x1080 -> 512x288 every weight is an exact eighth. */
        const int bottom = wy[row] >> 8;
        const __m128i top_weight = _mm_set1_epi16(8-bottom);
        const __m128i bottom_weight = _mm_set1_epi16(bottom);
        for (int col = 0; col < width; ++col) {
            const int x = xs[col], right = wx[col] >> 8;
            const uint8_t *a = bgr(lut,l0,u0,v0,x), *b = bgr(lut,l0,u0,v0,x+1);
            const uint8_t *c = bgr(lut,l1,u1,v1,x), *d = bgr(lut,l1,u1,v1,x+1);
            const __m128i wl = _mm_set1_epi16(8-right), wr = _mm_set1_epi16(right);
            __m128i upper = _mm_add_epi16(_mm_mullo_epi16(unpack(a),wl),_mm_mullo_epi16(unpack(b),wr));
            __m128i lower = _mm_add_epi16(_mm_mullo_epi16(unpack(c),wl),_mm_mullo_epi16(unpack(d),wr));
            upper = _mm_srli_epi16(_mm_mullo_epi16(upper,top_weight),4);
            lower = _mm_srli_epi16(_mm_mullo_epi16(lower,bottom_weight),4);
            __m128i pixel = _mm_srli_epi16(_mm_add_epi16(_mm_add_epi16(upper,lower),_mm_set1_epi16(2)),2);
            uint32_t packed = (uint32_t)_mm_cvtsi128_si32(_mm_packus_epi16(pixel,pixel));
            output[0]=(uint8_t)packed;output[1]=(uint8_t)(packed>>8);output[2]=(uint8_t)(packed>>16);
            output+=3;
        }
    }
}

__declspec(dllexport) void normalize_bgr(const uint8_t *image, int stride,
    const float *blue, const float *green, const float *red, float *output) {
    const int pixels = 512 * 288;
    for (int row = 0; row < 288; ++row) {
        const uint8_t *source = image + (size_t)row * stride;
        for (int col = 0; col < 512; ++col) {
            int index = row*512 + col;
            output[index] = red[source[2]];
            output[pixels+index] = green[source[1]];
            output[2*pixels+index] = blue[source[0]];
            source += 3;
        }
    }
}
